(5802411, 844916, 105457, '<td valign="top">For me this is a great abstract picture, but it is too faded out.</td>', 'For me this is a great abstract picture, but it is too faded out.', '2010-01-08 11:21:30.000000', NULL, 1),
(5802414, 844296, 105457, '<td valign="top">Good idea, but it''s too difficult to balance the exposure for both subjects, the moon is burned out.</td>', 'Good idea, but it''s too difficult to balance the exposure for both subjects, the moon is burned out.', '2010-01-08 11:22:09.000000', NULL, 1),
(5802415, 844223, 105457, '<td valign="top">Well, I guess you could receive some DNMC, but I liked the originality.</td>', 'Well, I guess you could receive some DNMC, but I liked the originality.', '2010-01-08 11:22:32.000000', NULL, 1),
(5802418, 845062, 105457, '<td valign="top">This could be a better shot if the focus was on the moon, and not on the three.</td>', 'This could be a better shot if the focus was on the moon, and not on the three.', '2010-01-08 11:22:56.000000', NULL, 1),
(5802421, 842968, 105457, '<td valign="top">Looks a bit flat, could use a bit of straightening.</td>', 'Looks a bit flat, could use a bit of straightening.', '2010-01-08 11:23:33.000000', NULL, 1),
(5802422, 843969, 105457, '<td valign="top">Unfortunately, too much exposure time, the moon is burned out.</td>', 'Unfortunately, too much exposure time, the moon is burned out.', '2010-01-08 11:23:54.000000', NULL, 1),
(5802424, 844309, 105457, '<td valign="top">You needed a much tighter crop, and less exposure time, the moon is burned.</td>', 'You needed a much tighter crop, and less exposure time, the moon is burned.', '2010-01-08 11:24:16.000000', NULL, 1),
(5802429, 845068, 105457, '<td valign="top">This shot is all about the upper half, unfortunately the moon is not defined, but the clouds and twigs are just brutal!</td>', 'This shot is all about the upper half, unfortunately the moon is not defined, but the clouds and twigs are just brutal!', '2010-01-08 11:24:54.000000', NULL, 1),
(5802431, 845074, 105457, '<td valign="top">It was cloudy there too? :-P<br/> <br/>Doesn''t really show much of the actual moon.</td>', 'It was cloudy there too? :-P Doesn''t really show much of the actual moon.', '2010-01-08 11:25:38.000000', NULL, 1),
(5802439, 843460, 105457, '<td valign="top">Could use a tighter crop, also a shorter exposure time.</td>', 'Could use a tighter crop, also a shorter exposure time.', '2010-01-08 11:29:40.000000', NULL, 1),
(5802442, 843632, 105457, '<td valign="top">Unfortunately one cannot make out the moon, the exposure was too long.</td>', 'Unfortunately one cannot make out the moon, the exposure was too long.', '2010-01-08 11:30:16.000000', NULL, 1),
(5802444, 842834, 105457, '<td valign="top">A bit out of focus, probably because of the great crop.</td>', 'A bit out of focus, probably because of the great crop.', '2010-01-08 11:30:38.000000', NULL, 1),
(5802588, 844730, 45672, '<td valign="top">Wonderful photo!  I really like the color and feel of this photo.  The vignette makes this a strong photos as well.  Congrats!</td>', 'Wonderful photo!  I really like the color and feel of this photo.  The vignette makes this a strong photos as well.  Congrats!', '2010-01-08 13:07:18.000000', NULL, 1),
