(5802777, 845068, 23484, '<td valign="top">This is freakin gorgeous.</td>', 'This is freakin gorgeous.', '2010-01-08 15:42:48.000000', NULL, 1),
(5802778, 844891, 23484, '<td valign="top">Nice shot. Too bad that street light was there.</td>', 'Nice shot. Too bad that street light was there.', '2010-01-08 15:43:25.000000', NULL, 1),
