(5802788, 843473, 23484, '<td valign="top">The clouds are great. Nice.</td>', 'The clouds are great. Nice.', '2010-01-08 15:46:05.000000', NULL, 1),
(5802789, 844916, 23484, '<td valign="top">I really like the green color in this. Very different from the masses.</td>', 'I really like the green color in this. Very different from the masses.', '2010-01-08 15:47:03.000000', NULL, 1),
(5803010, 844736, 45243, '<td valign="top">Very nice "cityscape"</td>', 'Very nice "cityscape"', '2010-01-08 19:11:25.000000', NULL, 1),
(5803014, 843970, 45243, '<td valign="top">Your capture  is somewhat reminiscent of the famous "EarthRise" photo taken from the Apollo 8 Spacecraft...very nice !</td>', 'Your capture  is somewhat reminiscent of the famous "EarthRise" photo taken from the Apollo 8 Spacecraft...very nice !', '2010-01-08 19:15:51.000000', NULL, 1),
(5803019, 844223, 45243, '<td valign="top">A unique and aesthetically pleasing solution to this challenge.  Well Done !</td>', 'A unique and aesthetically pleasing solution to this challenge.  Well Done !', '2010-01-08 19:20:53.000000', NULL, 1),
(5803023, 844179, 45243, '<td valign="top">Blue Moon, indeed !  Simple, crisp presentation....very nice !</td>', 'Blue Moon, indeed !  Simple, crisp presentation....very nice !', '2010-01-08 19:29:06.000000', NULL, 1),
(5803025, 845020, 45243, '<td valign="top">Great Title and Subject !  giggle giggle....</td>', 'Great Title and Subject !  giggle giggle....', '2010-01-08 19:30:44.000000', NULL, 1),
