(5803029, 844916, 45243, '<td valign="top">Surreal with wonderful colouring...</td>', 'Surreal with wonderful colouring...', '2010-01-08 19:32:48.000000', NULL, 1),
(5803033, 843979, 45243, '<td valign="top">Wonderful detail !!  You were perhaps on the ISS to taken this??? Ha !</td>', 'Wonderful detail !!  You were perhaps on the ISS to taken this??? Ha !', '2010-01-08 19:34:35.000000', NULL, 1),
(5803057, 844994, 45243, '<td valign="top">Love the colour and beautiful detail....I am in the camp that digital frame enhance  the presentation....Very Nice !</td>', 'Love the colour and beautiful detail....I am in the camp that digital frame enhance  the presentation....Very Nice !', '2010-01-08 19:52:32.000000', NULL, 1),
