(5803066, 845042, 45243, '<td valign="top">Nice effect and colours</td>', 'Nice effect and colours', '2010-01-08 20:17:32.000000', NULL, 1),
(5803067, 845071, 45243, '<td valign="top">Titles says it all....works well !</td>', 'Titles says it all....works well !', '2010-01-08 20:18:16.000000', NULL, 1),
(5803083, 845013, 45243, '<td valign="top">Great textures in low light...</td>', 'Great textures in low light...', '2010-01-08 20:42:23.000000', NULL, 1),
(5803091, 843875, 45243, '<td valign="top">excellent capture of the twilight moment...</td>', 'excellent capture of the twilight moment...', '2010-01-08 20:47:11.000000', NULL, 1),
(5803097, 844338, 10785, '<td valign="top">I really love the clouds below the moon! They look like upward brush strokes. The light shining on the snow creating the sparkle effect is magical!</td>', 'I really love the clouds below the moon! They look like upward brush strokes. The light shining on the snow creating the sparkle effect is magical!', '2010-01-08 20:50:30.000000', NULL, 1),
(5803100, 844948, 10785, '<td valign="top">Ultra sharp and not over sharpened which is awesome. I love that you can see the channels and craters of the moon. The texture of the craters on the top is perfect</td>', 'Ultra sharp and not over sharpened which is awesome. I love that you can see the channels and craters of the moon. The texture of the craters on the top is perfect', '2010-01-08 20:51:28.000000', NULL, 1),
(5803124, 845074, 15407, '<td valign="top">Awesome... It''s my favorite in the challenge!  What fine looking setup!</td>', 'Awesome... It''s my favorite in the challenge!  What fine looking setup!', '2010-01-08 21:07:08.000000', NULL, 1),
(5803125, 843979, 15407, '<td valign="top">A fine photo of the next outpost... seeing the mockups NASA &amp; Company have been building of the Lunar living/working quarters it seems as though I will see that come to fruitio n n my lifetime! Great photo and I''m looking forward to the details.</td>', 'A fine photo of the next outpost... seeing the mockups NASA & Company have been building of the Lunar living/working quarters it seems as though I will see that come to fruitio n n my lifetime! Great photo and I''m looking forward to the details.', '2010-01-08 21:07:11.000000', NULL, 1),
(5803134, 844709, 15407, '<td valign="top">This excellent photo has a real WOW factor that reminds me of the work of Ansel Adams.</td>', 'This excellent photo has a real WOW factor that reminds me of the work of Ansel Adams.', '2010-01-08 21:12:34.000000', NULL, 1),
(5803142, 845042, 15407, '<td valign="top">The cloud cover that you captured looks quite similiar to those which I had to work with... It took me a few hours to get a break in the clouds to get my photo, and I like yours better than mine!</td>', 'The cloud cover that you captured looks quite similiar to those which I had to work with... It took me a few hours to get a break in the clouds to get my photo, and I like yours better than mine!', '2010-01-08 21:15:47.000000', NULL, 1),
(5803145, 843456, 15407, '<td valign="top">That takes one incredible effort to get DOF that works with that distance! I''ve tried many techniques and have still not gotten acceptable results.</td>', 'That takes one incredible effort to get DOF that works with that distance! I''ve tried many techniques and have still not gotten acceptable results.', '2010-01-08 21:19:07.000000', NULL, 1),
(5803147, 844120, 15407, '<td valign="top">The natural lighting is my favorite featre of this great photo!</td>', 'The natural lighting is my favorite featre of this great photo!', '2010-01-08 21:20:12.000000', NULL, 1),
(5803154, 843468, 15407, '<td valign="top">One of my favorites in this challenge! If only there werea way to get rid of those ''jaggies'' in the trees!</td>', 'One of my favorites in this challenge! If only there werea way to get rid of those ''jaggies'' in the trees!', '2010-01-08 21:22:03.000000', NULL, 1),
(5803169, 844891, 15407, '<td valign="top">I like the capture of the building the best, although I believe that the photo would have been bore appealing if you had you cropped out the vechile in the lower right corner.</td>', 'I like the capture of the building the best, although I believe that the photo would have been bore appealing if you had you cropped out the vechile in the lower right corner.', '2010-01-08 21:33:41.000000', NULL, 1),
(5803380, 844709, 61084, '<td valign="top">This will ribbon or I''ll eat my camera strap. Very Ansel Adams in it''s feel. Great contrast and exposure, diagonal lines creating movement into the photo, sharp focus on the moon as well as the foreground and nice placement of the moon (ROT) within the composition. 10.</td>', 'This will ribbon or I''ll eat my camera strap. Very Ansel Adams in it''s feel. Great contrast and exposure, diagonal lines creating movement into the photo, sharp focus on the moon as well as the foreground and nice placement of the moon (ROT) within the composition. 10.', '2010-01-09 00:47:59.000000', NULL, 1),
(5803381, 843460, 61084, '<td valign="top">This is simple, but effective IMO. A very pretty scene in my book. 7</td>', 'This is simple, but effective IMO. A very pretty scene in my book. 7', '2010-01-09 00:49:23.000000', NULL, 1),
(5803382, 843468, 61084, '<td valign="top">Reminds me of the movie ET for some reason with the tree silhouettes against the moon. Good focus from foreground to the Moon, and I like the muted colors of the sky and clouds. I think I would have cropped along the right side more around the first major dip in the trees to bring the Moon a big more off the center area (not that it''s centered, but close) and maybe crop up to the base of the first group of trees on the bottom edge. These are just my thoughts, but I feel you will do well here. 8</td>', 'Reminds me of the movie ET for some reason with the tree silhouettes against the moon. Good focus from foreground to the Moon, and I like the muted colors of the sky and clouds. I think I would have cropped along the right side more around the first major dip in the trees to bring the Moon a big more off the center area (not that it''s centered, but close) and maybe crop up to the base of the first group of trees on the bottom edge. These are just my thoughts, but I feel you will do well here. 8', '2010-01-09 00:54:19.000000', NULL, 1),
(5803386, 845024, 61084, '<td valign="top">The moon looks awesome, but the sharpness on the foreground is soft and the halo whether it be glow from the Moon or processing takes away from the impact of the Moon exposure which again is excellent. 5</td>', 'The moon looks awesome, but the sharpness on the foreground is soft and the halo whether it be glow from the Moon or processing takes away from the impact of the Moon exposure which again is excellent. 5', '2010-01-09 00:58:14.000000', NULL, 1),
(5803394, 844338, 61084, '<td valign="top">This is one of those shots that is hard to crop, but would have benefited from better placement of the Moon. If you crop it you lose the impact of the housing and the lights so it''s troublesome in that manner. The contrast between the coolness (color) of the foreground moon glow with the golden warmth of the tungsten house lighting is beautiful. The color of the sky and feathery clouds looks great as well. The foreground is slightly soft in focus to my eyes which I could almost understand if the Moon was detailed, but in this case it''s not and it hurts the image a little bit. Still a pleasant scene and nice capture. 6</td>', 'This is one of those shots that is hard to crop, but would have benefited from better placement of the Moon. If you crop it you lose the impact of the housing and the lights so it''s troublesome in that manner. The contrast between the coolness (color) of the foreground moon glow with the golden warmth of the tungsten house lighting is beautiful. The color of the sky and feathery clouds looks great as well. The foreground is slightly soft in focus to my eyes which I could almost understand if the Moon was detailed, but in this case it''s not and it hurts the image a little bit. Still a pleasant scene and nice capture. 6', '2010-01-09 01:05:57.000000', NULL, 1),
(5803486, 845024, 112136, '<td valign="top">this is astonishing! Brilliant work. I think the dark portion in foreground would be better looking if it had a sharper edge covering the moon, just an opinion. a 9 from me</td>', 'this is astonishing! Brilliant work. I think the dark portion in foreground would be better looking if it had a sharper edge covering the moon, just an opinion. a 9 from me', '2010-01-09 05:15:53.000000', NULL, 1),
(5803488, 843979, 112136, '<td valign="top">so huge!! Did u get it from hubble ;-)</td>', 'so huge!! Did u get it from hubble ;-)', '2010-01-09 05:18:19.000000', NULL, 1),
(5803489, 843970, 112136, '<td valign="top">Great shot, a 9 form me</td>', 'Great shot, a 9 form me', '2010-01-09 05:19:41.000000', NULL, 1),
(5803506, 844736, 101702, '<td valign="top">Nice shot but looks like it is on a tilt. Would have given it an extra point if it were level.</td>', 'Nice shot but looks like it is on a tilt. Would have given it an extra point if it were level.', '2010-01-09 06:49:36.000000', NULL, 1),
(5803507, 844891, 101702, '<td valign="top">Nice shot but looks like it is on a tilt. I''d have given an extra point if it were level.</td>', 'Nice shot but looks like it is on a tilt. I''d have given an extra point if it were level.', '2010-01-09 06:49:41.000000', NULL, 1),
(5803751, 845068, 105130, '<td valign="top">This is . . . ethereal and beautiful. I hope it''s as appreciated by the other voters as much as me.</td>', 'This is . . . ethereal and beautiful. I hope it''s as appreciated by the other voters as much as me.', '2010-01-09 12:18:08.000000', NULL, 1);
