(5806773, 844742, 105441, '<td valign="top">Very unusual.  The time exposure on the steam is cool.</td>', 'Very unusual.  The time exposure on the steam is cool.', '2010-01-11 22:08:20.000000', NULL, 1),
(5806776, 843812, 105441, '<td valign="top">If only the moon and bird were separated from the tree!  Nice capture.</td>', 'If only the moon and bird were separated from the tree!  Nice capture.', '2010-01-11 22:10:32.000000', NULL, 1),
(5806780, 844120, 105441, '<td valign="top">Obviously a night scene lit by the moon, so I like the ''indirect'' approach to the theme.</td>', 'Obviously a night scene lit by the moon, so I like the ''indirect'' approach to the theme.', '2010-01-11 22:12:23.000000', NULL, 1),
(5806784, 844709, 105441, '<td valign="top">I would like a bit more contrast, especially in the trees.  But a nice shot.</td>', 'I would like a bit more contrast, especially in the trees.  But a nice shot.', '2010-01-11 22:14:45.000000', NULL, 1),
(5806787, 844223, 105441, '<td valign="top">This looks like a photo of a piece of art, so I don''t see what the photographer added.  But maybe I am wrong on that, will be interested in reading the photog''s comments.  15 January - Well voting closed, and now I know from the photog''s notes that this is a very creative image, created from a ''blank slate.''  Excellent work.<br/><br/><i>Message edited by author 2010-01-15 22:30:12.</i></td>', 'This looks like a photo of a piece of art, so I don''t see what the photographer added.  But maybe I am wrong on that, will be interested in reading the photog''s comments.  15 January - Well voting closed, and now I know from the photog''s notes that this is a very creative image, created from a ''blank slate.''  Excellent work.', '2010-01-11 22:17:06.000000', '2010-01-15 22:30:12.000000', 1),
(5806791, 844968, 105441, '<td valign="top">My favorite in this competition, although the moon is probably not contributing that much.</td>', 'My favorite in this competition, although the moon is probably not contributing that much.', '2010-01-11 22:22:59.000000', NULL, 1),
