INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5811277, 844709, 61084, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by DCNUTTER:</b></div><hr/><i> This will ribbon or I''ll eat my camera strap. Very Ansel Adams in it''s feel. Great contrast and exposure, diagonal lines creating movement into the photo, sharp focus on the moon as well as the foreground and nice placement of the moon (ROT) within the composition. 10. </i></td></tr></table> <br/> <br/>Nice to see I that I won''t have to eat my camera strap after all! Congrats on a ribbon well deserved.</td>', 'Originally posted by DCNUTTER: This will ribbon or I''ll eat my camera strap. Very Ansel Adams in it''s feel. Great contrast and exposure, diagonal lines creating movement into the photo, sharp focus on the moon as well as the foreground and nice placement of the moon (ROT) within the composition. 10.   Nice to see I that I won''t have to eat my camera strap after all! Congrats on a ribbon well deserved.', '2010-01-14 04:15:53.000000', NULL, 0),
(5811345, 845017, 63398, '<td valign="top">Great sky, nice definition of the moon. Should have finished better.</td>', 'Great sky, nice definition of the moon. Should have finished better.', '2010-01-14 07:52:31.000000', NULL, 0),
